function M.list()
    print(string.format("Catalog: %d function(s)", #M.entries))
    print(string.format("%-20s %-20s %-10s %s", "Name", "Signature", "Status", "Description"))
    print(string.rep("-", 90))
    for _, e in ipairs(M.entries) do
        print(string.format("%-20s %-20s %-10s %s", e.name, e.sig, e.status, e.desc))
    end
    return M.entries
end

function M.find(needle)
    if type(needle) ~= "string" or needle == "" then error("needle required") end
    local low = needle:lower()
    local out = {}
    for _, e in ipairs(M.entries) do
        if e.name:lower():find(low, 1, true) or e.desc:lower():find(low, 1, true)
            or (e.sig and e.sig:lower():find(low, 1, true)) then
            out[#out+1] = e
        end
    end
    print(string.format("catalog.find %q: %d hit(s)", needle, #out))
    for _, e in ipairs(out) do
        print(string.format("  %-20s %-20s %s", e.name, e.sig, e.desc))
    end
    return out
end

function M.by_tag(tag)
    if type(tag) ~= "string" or tag == "" then error("tag required") end
    local low = tag:lower()
    local out = {}
    for _, e in ipairs(M.entries) do
        for _, t in ipairs(e.tags or {}) do
            if t:lower() == low then out[#out+1]=e; break end
        end
    end
    print(string.format("catalog.by_tag %q: %d hit(s)", tag, #out))
    for _, e in ipairs(out) do print(string.format("  %-20s %-20s %s", e.name, e.sig, e.desc)) end
    return out
end

function M.by_status(status)
    if status == nil or status == "" then
        print(string.format("Catalog: %d function(s); use catalog.by_status('candidate') to filter", #M.entries))
        return M.entries
    end
    local low = status:lower()
    local out = {}
    for _, e in ipairs(M.entries) do
        if e.status:lower() == low then out[#out+1]=e end
    end
    print(string.format("catalog.by_status %q: %d hit(s)", status, #out))
    for _, e in ipairs(out) do print(string.format("  %-20s %-20s %s", e.name, e.sig, e.desc)) end
    return out
end

function M.hunt(tag_or_needle, base, size, opts)
    tag_or_needle = tag_or_needle or "economy"
    base = base or 0x00400000; size = size or 0x300000
    opts = opts or {}
    local shallow = opts.shallow
    local list = M.by_tag(tag_or_needle)
    if #list == 0 then list = M.find(tag_or_needle) end
    if #list == 0 then print("catalog.hunt: no entries for " .. tostring(tag_or_needle)); return {} end
    local finder = require("finder")
    local auto = require("auto")
    for _, e in ipairs(list) do
        if shallow then
            -- just print candidate entry, no memory scan (useful on Linux / for planning)
            print(string.format("  %-20s %-20s %s", e.name, e.sig, e.desc))
        else
            local needle = e.name:gsub("^Get",""):gsub("^Set",""):gsub("^Add",""):gsub("^Is","")
            if needle:match("^[A-Z][a-z]+[A-Z]") then needle = needle:match("^[A-Z][a-z]+") or needle end
            if auto and auto.discover then
                print(string.format("\n-- %s (%s) -- needle %q --", e.name, e.desc, needle))
                pcall(auto.discover, needle, base, size, { limit = 2 })
            elseif finder and finder.string_func then
                print(string.format("\n-- %s --", e.name))
                pcall(finder.string_func, needle, base, size)
            end
        end
    end
    return list
end

function M.hunt_economy(base, size) return M.hunt("economy", base, size) end
function M.hunt_building(base, size) return M.hunt("building", base, size) end
function M.hunt_world(base, size) return M.hunt("world", base, size) end

function M.export(path)
    path = path or "catalog_export.lua"
    local f, err = io.open(path, "w")
    if not f then error("cannot open " .. path .. ": " .. tostring(err)) end
    f:write("-- catalog export " .. os.date("%Y-%m-%d %H:%M:%S") .. ", " .. tostring(#M.entries) .. " entries\n")
    f:write("-- load with: dofile('" .. path:gsub("'", "\\'") .. "') then catalog.register_all()\n")
    f:write('local catalog = require("catalog")\n')
    for _, e in ipairs(M.entries) do
        f:write(string.format("catalog.entries[#catalog.entries+1] = { name=%q, sig=%q, desc=%q, tags={", e.name, e.sig, e.desc))
        for i, t in ipairs(e.tags or {}) do f:write(string.format("%q", t)); if i < #e.tags then f:write(",") end end
        f:write(string.format("}, status=%q }\n", e.status or "candidate"))
    end
    f:close()
    print(string.format("catalog.export: wrote %d entries -> %s", #M.entries, path))
    return path
end

-- Try to register entries that have a resolvable pattern via sig/scan;
-- otherwise just prints what would be registered (dry=true).
function M.register_all(dry)
    local game = require("gamecalls")
    local n = 0
    for _, e in ipairs(M.entries) do
        if e.address and e.address ~= 0 then
            if dry then
                print(string.format("[dry] %s @ 0x%08X %s", e.name, e.address, e.sig))
            else
                local ok, err = pcall(game.register, e.name, e.address, e.sig, e.desc)
                if ok then n=n+1 else print("register failed " .. e.name .. ": " .. tostring(err)) end
            end
        end
    end
    if n == 0 and not dry then
        print("catalog.register_all: no entries have verified addresses yet; use finder/auto to fill `address`, or register manually via catalog.find + game.register")
    else
        print(string.format("catalog.register_all: %d registered", n))
    end
    return n
end

return M
